package com.dispatchpro.driver;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.widget.*;
import org.json.JSONObject;

/** User-led sequential Android requests. Denials never cause an automatic loop. */
final class NativePermissions {
 private final Activity host;private final boolean driver;private boolean busy;private String step="";
 NativePermissions(Activity host,boolean driver){this.host=host;this.driver=driver;}
 boolean busy(){return busy;}
 boolean granted(String permission){return host.checkSelfPermission(permission)==PackageManager.PERMISSION_GRANTED;}
 void firstRun(){if(!host.getSharedPreferences("permission-guide",0).getBoolean("shown-v1",false)&&!busy){host.getSharedPreferences("permission-guide",0).edit().putBoolean("shown-v1",true).apply();show();}}
 void show(){if(busy)return;busy=true;LinearLayout content=new LinearLayout(host);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(32,16,32,16);content.setLayoutDirection(android.view.View.LAYOUT_DIRECTION_RTL);
  TextView help=new TextView(host);help.setTextSize(16);help.setText("لعمل التطبيق بشكل صحيح نحتاج الأذونات التالية. يمكنك المتابعة عند الرفض وتفعيل الوظيفة لاحقًا من الإعدادات.\n\nالموقع الدقيق: "+ready(granted(Manifest.permission.ACCESS_FINE_LOCATION))+" — "+(driver?"مشاركة موقع السيارة أثناء العمل":"تحديد نقطة الالتقاء")+"\n\nالإشعارات: "+ready(Build.VERSION.SDK_INT<33||granted(Manifest.permission.POST_NOTIFICATIONS))+" — الطلبات والرسائل والمكالمات\n\nالميكروفون: "+ready(granted(Manifest.permission.RECORD_AUDIO))+" — مكالمات الرحلة"+(driver?" والمخشيرة\n\nالموقع بالخلفية: يُطلب منفصلًا لاستعادة الموقع بعد إعادة إنشاء العملية أثناء وضع متاح. Android Force Stop اليدوي قد يتطلب فتح التطبيق مجددًا.":""));content.addView(help);
  ScrollView scroll=new ScrollView(host);scroll.addView(content);new AlertDialog.Builder(host).setTitle("أذونات التطبيق").setView(scroll).setPositiveButton("متابعة وتفعيل الأذونات",(d,w)->next()).setNegativeButton("لاحقًا",(d,w)->busy=false).setNeutralButton("فتح الإعدادات",(d,w)->{busy=false;settings();}).setOnCancelListener(d->busy=false).show();
 }
 private static String ready(boolean value){return value?"جاهز":"غير جاهز";}
 private void next(){android.content.SharedPreferences asked=host.getSharedPreferences("permission-asked",0);step=PermissionPlan.next(Build.VERSION.SDK_INT,Build.VERSION.SDK_INT<33||granted(Manifest.permission.POST_NOTIFICATIONS),granted(Manifest.permission.ACCESS_FINE_LOCATION),granted(Manifest.permission.RECORD_AUDIO),asked.getBoolean("notifications",false),asked.getBoolean("location",false),asked.getBoolean("microphone",false));if(step.equals("done")){busy=false;background();return;}asked.edit().putBoolean(step,true).apply();String[] permissions=step.equals("notifications")?new String[]{Manifest.permission.POST_NOTIFICATIONS}:step.equals("location")?new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION}:new String[]{Manifest.permission.RECORD_AUDIO};host.requestPermissions(permissions,701);}
 boolean result(int code){if(code!=701&&code!=702)return false;if(code==702){busy=false;return true;}next();return true;}
 private void background(){if(!driver||Build.VERSION.SDK_INT<29||!granted(Manifest.permission.ACCESS_COARSE_LOCATION)||granted(Manifest.permission.ACCESS_BACKGROUND_LOCATION))return;android.content.SharedPreferences store=host.getSharedPreferences("permission-guide",0);if(store.getBoolean("background-explained",false))return;store.edit().putBoolean("background-explained",true).apply();new AlertDialog.Builder(host).setTitle("الموقع أثناء العمل بالخلفية").setMessage("أثناء وضع متاح تستخدم خدمة ظاهرة بإشعار دائم الموقع. لاستعادة الموقع بعد إعادة إنشاء عملية التطبيق بالخلفية، اختر السماح طوال الوقت في إذن الموقع. لا يتم تتبع الموقع عند غير متاح. يمكنك ترك الإعداد كما هو والاستمرار؛ استعادة الخدمة بعد إغلاق العملية قد تتطلب فتح التطبيق.").setPositiveButton(Build.VERSION.SDK_INT>=30?"فتح إعدادات الموقع":"تفعيل",(d,w)->{if(PermissionPlan.backgroundSettings(Build.VERSION.SDK_INT))settings();else{busy=true;host.requestPermissions(new String[]{Manifest.permission.ACCESS_BACKGROUND_LOCATION},702);}}).setNegativeButton("لاحقًا",null).show();}
 void settings(){host.startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+host.getPackageName())));}
 void diagnostics(){try{if(BuildConfig.FLAVOR.equals("radio")){radioDiagnostics();return;}JSONObject state=state();StringBuilder text=new StringBuilder();for(String key:new String[]{"الإشعارات","الموقع الدقيق","الموقع بالخلفية","الميكروفون","تحسين البطارية","خدمة العمل","FCM / Push","Realtime"})text.append(key).append(": ").append(state.optString(key)).append("\n\n");new AlertDialog.Builder(host).setTitle("الأذونات والصوت").setMessage(text+"اختبر النغمات أو افتح إعدادات القناة. الصوت يتبع مستوى الهاتف وعدم الإزعاج.").setPositiveButton("الأذونات",(d,w)->show()).setNeutralButton("النغمات",(d,w)->sounds()).setNegativeButton("إغلاق",null).show();}catch(Exception ignored){}}
 private void radioDiagnostics()throws Exception{
  boolean exempt=host.getSystemService(PowerManager.class).isIgnoringBatteryOptimizations(host.getPackageName());
  JSONObject metrics=new JSONObject(host.getSharedPreferences("communication-metrics",0).getAll());
  String text="خدمة المخشير: "+(DriverForegroundService.running?"تعمل":"متوقفة")+"\n\nالبطارية: "+(exempt?"غير مقيدة":"تحسين البطارية فعال")+"\n\nمنح الموجة: "+metrics.optLong("pttFloorGrantMs",-1)+" ms\nجاهزية النقل: "+metrics.optLong("pttPressToTransportMs",-1)+" ms\n\nفعّل الصوت مرة واحدة قبل قفل الشاشة. للاستقبال المستمر اسمح باستثناء البطارية وأبقِ إشعار NM RADIO ظاهرًا. إيقاف التطبيق إجباريًا يتطلب فتحه مجددًا.";
  new AlertDialog.Builder(host).setTitle("NM RADIO · الخلفية والصوت").setMessage(text).setPositiveButton("الأذونات",(d,w)->show()).setNeutralButton(exempt?"إعدادات البطارية":"السماح بالخلفية",(d,w)->{
   try{host.startActivity(exempt?new Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS):new Intent(android.provider.Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,android.net.Uri.parse("package:"+host.getPackageName())));}catch(RuntimeException unavailable){settings();}
  }).setNegativeButton("نسخ التشخيص",(d,w)->{try{host.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(android.content.ClipData.newPlainText("NM RADIO diagnostics",DriverDiagnostics.read(host).toString()));}catch(Exception ignored){}}).show();
 }
 JSONObject state()throws Exception{boolean fcm=false;try{String audience=driver?"DRIVER":"CUSTOMER";fcm=!((String)BuildConfig.class.getField(audience+"_FIREBASE_APP_ID").get(null)).isEmpty();}catch(Exception ignored){}long at=host.getSharedPreferences("driver-health",0).getLong("realtimeAt",0);return new JSONObject().put("الإشعارات",ready(CommunicationNotifications.permitted(host))).put("الموقع الدقيق",ready(granted(Manifest.permission.ACCESS_FINE_LOCATION))).put("الموقع بالخلفية",driver?(Build.VERSION.SDK_INT<29?"جاهز":ready(granted(Manifest.permission.ACCESS_BACKGROUND_LOCATION))):"غير مطلوب").put("الميكروفون",ready(granted(Manifest.permission.RECORD_AUDIO))).put("تحسين البطارية",host.getSystemService(PowerManager.class).isIgnoringBatteryOptimizations(host.getPackageName())?"غير مقيد":"فعال — يمكن مراجعة إعدادات التطبيق").put("خدمة العمل",driver?(DriverForegroundService.running?"تعمل":"متوقفة"):(CallAudioService.running?"مكالمة فعالة":"غير مطلوبة خارج المكالمة")).put("FCM / Push",fcm?(host.getSharedPreferences(driver?"driver-push":"customer-push",0).getBoolean("bound",false)?"مسجل":"مهيأ — لم يسجل الجهاز بعد"):"غير مهيأ").put("Realtime",System.currentTimeMillis()-at<35000?"متصل":"غير متصل / التطبيق في الخلفية");}
 private void sounds(){String[] labels=driver?new String[]{"طلب رحلة","دردشة","مكالمة","PTT"}:new String[]{"دردشة","مكالمة","ARRIVED"};int[] kinds=driver?new int[]{0,1,2,3}:new int[]{1,2,4};new AlertDialog.Builder(host).setTitle("اختبار النغمات").setItems(labels,(d,index)->{int kind=kinds[index];String channel=CommunicationNotifications.soundChannel(host,kind);new AlertDialog.Builder(host).setTitle(labels[index]).setMessage("القناة: "+channel).setPositiveButton("تجربة النغمة",(a,b)->CommunicationNotifications.test(host,kind)).setNeutralButton("إعدادات القناة",(a,b)->{if(Build.VERSION.SDK_INT>=26)host.startActivity(new Intent(android.provider.Settings.ACTION_CHANNEL_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,host.getPackageName()).putExtra(android.provider.Settings.EXTRA_CHANNEL_ID,channel));}).setNegativeButton("إغلاق",null).show();}).show();}
}
